#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <iomanip>

using namespace std;

vector<string> spliString(string s,char del){
    vector<string> res;
    stringstream ss(s);
    string t;
    while(getline(ss,t,del)){
        res.push_back(t);
    }
    return res;
}

int main(){
    long long n;
    cin>>n;

    string pre;
    cin>>pre;
    char del = ':';

    n--;
    while(n--){
        vector<string> ptime = spliString(pre, del);
        int phour = stoi(ptime[0]);
        int pmin = stoi(ptime[1]);
        int pst = stoi(ptime[2]);

        string nex;
        cin>>nex;
        vector<string> ntime = spliString(nex, del);
        int nhour = stoi(ntime[0]);
        int nmin = stoi(ntime[1]);
        int nst = stoi(ntime[2]);

        if(nhour<phour){
            nhour+=24;
            if(nmin<pmin){
                nhour--;
                nmin+=60;
            }
            if(nst<pst){
                nmin--;
                nst+=60;
            }
        }

        if(nhour==phour&&nmin<pmin){
            nhour+=24;
            if(nmin<pmin){
                nhour--;
                nmin+=60;
            }
            if(nst<pst){
                nmin--;
                nst+=60;
            }
        }

        if(nhour==phour&&nmin==pmin&&nst<pst){
            nhour+=24;
            if(nmin<pmin){
                nhour--;
                nmin+=60;
            }
            if(nst<pst){
                nmin--;
                nst+=60;
            }
        }

        int sums = (nhour-phour)*3600+(nmin-pmin)*60+nst-pst;

        double cil = sums/60.00;
        cout<<fixed<<setprecision(2)<<cil<<" ";

        pre = nex;
    }
}
